def apply_vietnamese_explanations(items):
    missing = [item.get("id") for item in items if item.get("id") not in EXPLANATIONS_VI]
    if missing:
        raise ValueError(f"Missing Vietnamese explanations: {missing}")
    for item in items:
        item["explanationVi"] = EXPLANATIONS_VI[item["id"]]
